class Solution:
    def minMutation(self,startGene,endGene,bank):
        available=set(bank);queue=deque([(startGene,0)]);seen={startGene}
        while queue:
            word,distance=queue.popleft()
            if word==endGene:return distance
            for i in range(len(word)):
                for char in 'ACGT':
                    next_word=word[:i]+char+word[i+1:]
                    if next_word in available and next_word not in seen:seen.add(next_word);queue.append((next_word,distance+1))
        return -1
